import fs from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";

export const name = "building-loop-real-audit-witness";
export const inject = ["agentPresets", "agents", "sessions", "sessionController", "tools", "llm"];

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
const home = process.env.BUILDING_LOOP_REAL_RUN;
const route = { provider: "deepseek-official", model: "deepseek-flash", reasoningEffort: "off" };
const tracked = new Set([
  "turn/start", "turn/end", "step/start", "step/end", "user/message",
  "assistant/message", "assistant/attempt", "tool/call", "tool/result",
  "subagent/catalog", "subagent/descriptor", "agent/inbox/claimed",
  "agent/inbox/inserted", "session/model",
]);
const allowed = new Set(["read", "write", "edit", "skill", "subagent", "send_message",
  "list_agents", "wait_agent", "list_subagent_models", "todo_write"]);
const fileTools = new Set(["read", "write", "edit"]);

function json(data) {
  const key = process.env.DEEPSEEK_API_KEY;
  const text = JSON.stringify(data, (_key, value) => typeof value === "bigint" ? value.toString() : value);
  return key ? text.replaceAll(key, "[redacted]") : text;
}

function append(name, data) {
  fs.appendFileSync(path.join(home, name), json({ time: Date.now(), ...data }) + "\n", "utf8");
}

function finished(data) {
  fs.writeFileSync(path.join(home, "finished.json"), json(data) + "\n", "utf8");
}

function inside(root, target) {
  const relative = path.relative(root, target);
  return relative !== ".." && !relative.startsWith(".." + path.sep) && !path.isAbsolute(relative);
}

export function apply(ctx) {
  const groups = new Map();
  const identities = new Map();
  let active = null;
  let initiated = false;
  const progress = data => append("progress.jsonl", data);
  const scopeOf = sessionId => identities.get(sessionId) ?? active;

  ctx.tools.guard(exec => {
    if (!exec.agent) return "Fixture tools require an agent.";
    const group = groups.get(scopeOf(exec.agent.id));
    if (!group) return "Fixture is inactive.";
    const args = exec.arguments ?? {};
    let denial;
    if (!allowed.has(exec.name)) {
      denial = "Use only the workspace file, skill and native subagent tools in this fixture.";
    } else if (fileTools.has(exec.name)) {
      const candidate = path.resolve(group.workspace, typeof args.file_path === "string" ? args.file_path : "");
      const skillRoot = path.join(home, "isolated-home", "profiles", "web", "node_modules",
        "dsh-building-loop", "skills");
      if (!(inside(group.workspace, candidate) || exec.name === "read" && inside(skillRoot, candidate))) {
        denial = "The test permits file access only inside its fixture or bundled skill documents.";
      }
    } else if (exec.name === "skill" && !["project-index", "dispatch-protocol"].includes(args.name)) {
      denial = "Use the two building-loop skills for this test.";
    } else if (exec.name === "subagent") {
      if (args.cwd && path.resolve(group.workspace, args.cwd) !== group.workspace) {
        denial = "Subagents must stay in the same fixture workspace.";
      } else if (args.provider && args.provider !== route.provider || args.model && args.model !== route.model) {
        denial = "Both arms and every role must use the same test model.";
      } else if (group.ids.size >= 5) {
        denial = "This small fixture has a four-child safety budget.";
      }
    }
    if (denial) {
      append("events.jsonl", { group: group.name, sid: exec.agent.id, type: "fixture/denied",
        data: { name: exec.name, path: args.file_path ?? args.cwd, reason: denial } });
    }
    return denial;
  });

  ctx.on("session/event", (session, event) => {
    if (!tracked.has(event.type)) return;
    const label = scopeOf(session.id);
    const group = groups.get(label);
    if (!group) return;
    identities.set(session.id, label);
    group.ids.add(session.id);
    group.lastEvent = Date.now();
    const data = event.type === "assistant/message"
      ? { turn: event.data.turn, step: event.data.step, usage: event.data.usage,
          source: { provider: event.data.message?.source?.provider, model: event.data.message?.source?.model },
          content: event.data.message?.content?.filter(block => block.type !== "thinking") }
      : event.type === "assistant/attempt"
        ? { turn: event.data.turn, step: event.data.step, stream: event.data.stream }
        : event.data;
    append("events.jsonl", { group: label, sid: session.id, seq: event.seq, type: event.type, data });
    if (event.type === "step/start") group.steps++;
    if (event.type === "subagent/catalog") {
      identities.set(event.data.childId, label);
      group.ids.add(event.data.childId);
      progress({ group: label, event: "child", sid: event.data.childId, label: event.data.label });
    }
    if (event.type === "turn/end") {
      const reason = event.data?.reason?.kind ?? "unknown";
      if (reason === "error" || reason === "blocked" || reason === "max-tokens") {
        progress({ group: label, event: "turn-end", sid: session.id, reason, detail: event.data?.reason?.code });
      }
    }
  });

  async function allIdle(group) {
    const agents = [...group.ids].map(id => ctx.agents.get(id)).filter(Boolean);
    return Promise.race([Promise.all(agents.map(agent => agent.whenIdle())).then(() => true), sleep(550).then(() => false)]);
  }

  async function runGroup(name) {
    const directory = path.join(home, name);
    const group = { name, workspace: path.join(directory, "workspace"), ids: new Set(), steps: 0, lastEvent: Date.now() };
    groups.set(name, group);
    active = name;
    const started = Date.now();
    const { sessionId } = await ctx.sessionController.create({ cwd: group.workspace, agentPreset: "building-loop" });
    group.root = sessionId;
    group.ids.add(sessionId);
    identities.set(sessionId, name);
    const agent = ctx.agents.get(sessionId);
    await ctx.sessionController.selectModel({ sessionId, ...route });
    const declared = ctx.tools.schemas(agent).map(definition => definition.name);
    progress({ group: name, event: "start", sid: sessionId, tools: declared.filter(tool => allowed.has(tool)) });
    const requestId = randomUUID();
    await ctx.sessionController.prompt({
      sessionId, requestId, clientTimeZone: "Asia/Shanghai",
      content: [{ type: "text", text: fs.readFileSync(path.join(directory, "prompt.txt"), "utf8") }],
    }, AbortSignal.timeout(10000));
    let end = "deadline";
    while (Date.now() - started < 260000) {
      if (group.steps > 64) {
        end = "step-budget";
        break;
      }
      if (await allIdle(group)) {
        const hasFinal = fs.existsSync(path.join(group.workspace, "records", "audit-final.json"));
        const hasLedger = fs.existsSync(path.join(group.workspace, "ledger.md"));
        if (hasFinal && hasLedger && Date.now() - group.lastEvent > 1800) {
          end = "artifacts-present";
          break;
        }
        if (Date.now() - group.lastEvent > 14000) {
          end = "idle-without-all-artifacts";
          break;
        }
      }
      await sleep(600);
    }
    const result = { group: name, event: "finish", sid: sessionId, end, wallMs: Date.now() - started,
      steps: group.steps, members: [...group.ids] };
    progress(result);
    fs.writeFileSync(path.join(directory, "host-result.json"), json(result) + "\n", "utf8");
    active = null;
    if (end === "deadline" || end === "step-budget") throw new Error(name + " exceeded its test budget");
    return result;
  }

  const timer = setInterval(async () => {
    if (initiated) return;
    try {
      const preset = (await ctx.agentPresets.list()).find(row => row.id === "building-loop");
      if (!preset) return;
      initiated = true;
      if (preset.broken) throw new Error("building-loop preset is broken");
      const info = await ctx.llm.resolveModelInfo(route.provider, route.model);
      progress({ event: "route-ready", provider: route.provider, model: route.model, title: info?.name });
      const reuse = await runGroup("reuse");
      if (reuse.steps === 0) throw new Error("No model step ran in the first arm");
      const fresh = await runGroup("fresh");
      finished({ status: "observed", groups: [reuse, fresh] });
    } catch (error) {
      initiated = true;
      progress({ event: "error", error: String(error) });
      finished({ status: "error", error: String(error) });
    }
  }, 300);
  ctx.on("dispose", () => clearInterval(timer));
}
